list_products.code:
use WebCommander\Resources\Products\Products;

$response = Products::listProducts($client, ['limit' => 20]);

foreach ($response->map['products'] as $product) {
    echo $product['id'], ' ', $product['name'], ' (', $product['sku'], '): ', $product['base_price'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' products in total', PHP_EOL;

create_product.code:
use WebCommander\Resources\Products\Products;

$response = Products::createProduct($client, [
    'name' => 'Blue Mug', 'sku' => 'MUG-BLUE', 'base_price' => 12.5, 'transaction_no' => 'IMPORT-2026-10-18',
], transactionNo: 'IMPORT-2026-10-18');

$product = $response->map['product'];
echo $product['id'], ' ', $product['sku'], ' ', $product['status'], ' ', $product['transaction_no'], PHP_EOL;

get_product.code:
use WebCommander\Resources\Products\Products;

$response = Products::getProduct($client, 101);

$product = $response->map['product'];
echo $product['name'], ' (', $product['sku'], '): ', $product['base_price'], PHP_EOL;
echo $product['product_pricing_and_stock']['available_stock'], ' in stock', PHP_EOL;

update_product.code:
use WebCommander\Resources\Products\Products;

$response = Products::updateProduct($client, 101, [
    'name' => 'Cotton T-Shirt', 'sku' => 'TSHIRT-001', 'base_price' => 25.0, 'product_type' => 'physical',
    'available' => true, 'is_on_sale' => false, 'available_on_date_range' => false,
    'available_on_weekdays' => ['enabled' => false, 'weekdays' => []],
    'available_for' => 'all', 'selected_customers' => ['customers' => [], 'groups' => []],
    'invoice_note' => 'Ships in 2 business days',
    'advanced' => ['advance_information' => ['mpn' => 'MPN-0001']],
]);

$product = $response->map['product'];
echo $product['invoice_note'], ', ', $product['advanced']['advance_information']['mpn'], ', version ', $product['version'], PHP_EOL;

patch_product.code:
use WebCommander\Resources\Products\Products;

$response = Products::patchProduct($client, 101, ['base_price' => 27.5]);

$product = $response->map['product'];
echo $product['name'], ': ', $product['base_price'], ', version ', $product['version'], PHP_EOL;

import_product_reviews.code:
use WebCommander\Resources\Products\Products;

$response = Products::importProductReviews($client, 101, ['product' => ['reviews' => [
    ['name' => 'Sam Lee', 'email' => 'sam@example.com', 'rating' => 5, 'review' => 'Great shirt', 'status' => 'approved'],
]]], transactionNo: 'IMPORT-2026-10-18');

foreach ($response->map['product']['reviews'] as $review) {
    echo $review['id'], ' ', $review['name'], ' ', $review['rating'], ' ', $review['status'], PHP_EOL;
}

get_product_stock.code:
use WebCommander\Resources\Products\Products;

$response = Products::getProductStock($client, 101);

foreach ($response->map['locations'] as $location) {
    echo $location['warehouse'], ' ', $location['warehouse_name'], ': ', $location['stock'], $location['is_default'] ? ' (default)' : '', PHP_EOL;
}
echo $response->map['available_stock'], ' in total', PHP_EOL;

update_product_stock.code:
use WebCommander\Resources\Products\Products;

$response = Products::updateProductStock($client, 101, [
    'note' => 'Restock',
    'locations' => [
        ['warehouse' => 1, 'stock' => 10, 'low_stock_level' => 2, 'is_default' => true],
        ['warehouse' => 4, 'stock' => 30, 'low_stock_level' => 5, 'is_default' => false],
    ],
]);

echo $response->map['available_stock'], ' in total', PHP_EOL;

check_product_sku.code:
use WebCommander\Resources\Products\Products;

$response = Products::checkProductSku($client, 'TSHIRT-001');

echo $response->map['available'] ? 'SKU is free' : 'SKU is used by product ' . $response->map['product']['id'], PHP_EOL;

